/* Service worker, generated by scripts/build.py from scripts/sw.template.js. */
const VERSION = '__VERSION__';
const SHELL = __SHELL__;
const THUMBS = __THUMBS__;
const APP_CACHE = `ny26-app-${VERSION}`;
const IMG_CACHE = 'ny26-img';
const TILE_CACHE = 'ny26-tiles';
const TILE_LIMIT = 1500;

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const app = await caches.open(APP_CACHE);
    await app.addAll(SHELL);
    const img = await caches.open(IMG_CACHE);
    // Thumbnails are best effort: a missing one should not block installation.
    await Promise.allSettled(THUMBS.map((u) => img.add(u)));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys
      .filter((k) => k.startsWith('ny26-app-') && k !== APP_CACHE)
      .map((k) => caches.delete(k)));
    await self.clients.claim();
  })());
});

async function trimTiles() {
  const cache = await caches.open(TILE_CACHE);
  const keys = await cache.keys();
  for (let i = 0; i < keys.length - TILE_LIMIT; i++) await cache.delete(keys[i]);
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);

  if (url.hostname === 'tile.openstreetmap.org') {
    event.respondWith((async () => {
      const cache = await caches.open(TILE_CACHE);
      const hit = await cache.match(req);
      if (hit) return hit;
      try {
        const res = await fetch(req);
        if (res.ok) { cache.put(req, res.clone()); trimTiles(); }
        return res;
      } catch (e) {
        return new Response('', { status: 504 });
      }
    })());
    return;
  }

  if (url.origin !== self.location.origin) return;

  if (url.pathname.endsWith('/data/trip.json')) {
    // Network first so edits show up; cache when offline.
    event.respondWith((async () => {
      const cache = await caches.open(APP_CACHE);
      try {
        const res = await fetch(req);
        if (res.ok) cache.put(req, res.clone());
        return res;
      } catch (e) {
        return (await cache.match(req)) || Response.error();
      }
    })());
    return;
  }

  if (url.pathname.includes('/assets/img/')) {
    event.respondWith((async () => {
      const cache = await caches.open(IMG_CACHE);
      const hit = await cache.match(req);
      if (hit) return hit;
      const res = await fetch(req);
      if (res.ok) cache.put(req, res.clone());
      return res;
    })());
    return;
  }

  event.respondWith((async () => {
    const hit = await caches.match(req, { ignoreSearch: true });
    if (hit) return hit;
    try {
      return await fetch(req);
    } catch (e) {
      if (req.mode === 'navigate') return caches.match('index.html');
      throw e;
    }
  })());
});

// The page asks for every full-size photo when the user taps "Guardar para usar sin señal".
self.addEventListener('message', (event) => {
  if (event.data?.type !== 'cache-images') return;
  event.waitUntil((async () => {
    const cache = await caches.open(IMG_CACHE);
    const urls = event.data.urls || [];
    let done = 0;
    for (const u of urls) {
      try {
        if (!(await cache.match(u))) await cache.add(u);
      } catch (e) { /* keep going */ }
      done++;
      if (done % 5 === 0 || done === urls.length) {
        event.source?.postMessage({ type: 'cache-progress', done, total: urls.length });
      }
    }
  })());
});
